create table if not exists presentations (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  title text not null,\n  topic text,\n  audience text,\n  tone text,\n  template_id uuid,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists design_templates (\n  id uuid primary key default gen_random_uuid(),\n  name text not null,\n  font_pairing text,\n  primary_color text default '#1a1a2e',\n  accent_color text default '#16213e',\n  bg_color text default '#ffffff',\n  layout_type text default 'bullet',\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists slides (\n  id uuid primary key default gen_random_uuid(),\n  presentation_id uuid references presentations(id) on delete cascade,\n  slide_number int not null default 1,\n  title text,\n  body_content text,\n  speaker_notes text,\n  layout_type text default 'bullet',\n  ai_source text,\n  ai_confidence numeric,\n  ai_review_status text default 'unreviewed',\n  created_at timestamptz not null default now()\n);\n\nalter table presentations enable row level security;\nalter table design_templates enable row level security;\nalter table slides enable row level security;\n\ndrop policy if exists \"presentations_v1_read\" on presentations;\ncreate policy \"presentations_v1_read\" on presentations for select using (true);\ndrop policy if exists \"presentations_v1_write\" on presentations;\ncreate policy \"presentations_v1_write\" on presentations for all using (true) with check (true);\n\ndrop policy if exists \"design_templates_v1_read\" on design_templates;\ncreate policy \"design_templates_v1_read\" on design_templates for select using (true);\ndrop policy if exists \"design_templates_v1_write\" on design_templates;\ncreate policy \"design_templates_v1_write\" on design_templates for all using (true) with check (true);\n\ndrop policy if exists \"slides_v1_read\" on slides;\ncreate policy \"slides_v1_read\" on slides for select using (true);\ndrop policy if exists \"slides_v1_write\" on slides;\ncreate policy \"slides_v1_write\" on slides for all using (true) with check (true);\n\ninsert into design_templates (name, font_pairing, primary_color, accent_color, bg_color, layout_type)\nvalues\n  ('Boardroom Blue', 'Inter / Merriweather', '#1a1a2e', '#0f3460', '#ffffff', 'bullet'),\n  ('Classroom Bright', 'Poppins / Open Sans', '#2d6a4f', '#95d5b2', '#f8f9fa', 'bullet'),\n  ('Executive Slate', 'Helvetica / Georgia', '#2b2d42', '#8d99ae', '#ffffff', 'bullet'),\n  ('Coach Warm', 'DM Sans / Lora', '#6a040f', '#9d0208', '#fff8f0', 'bullet')\non conflict do nothing;\n\ninsert into presentations (id, title, topic, audience, tone, template_id)\nselect '11111111-1111-1111-1111-111111111111', 'Photosynthesis for 8th Grade', 'photosynthesis', '8th grade students', 'classroom lecture', id\nfrom design_templates where name = 'Classroom Bright'\non conflict do nothing;\n\ninsert into slides (presentation_id, slide_number, title, body_content, speaker_notes, layout_type, ai_source, ai_confidence, ai_review_status)\nvalues\n  ('11111111-1111-1111-1111-111111111111', 1, 'What is Photosynthesis?', 'Plants convert sunlight into energy\nChlorophyll captures light energy\nProduces glucose and oxygen', 'Start with the big idea — plants make their own food using sunlight.', 'bullet', 'openai', 0.95, 'approved'),\n  ('11111111-1111-1111-1111-111111111111', 2, 'The Process', 'Light energy + water + CO2\nOccurs in chloroplasts\nProduces glucose + oxygen', 'Walk through inputs and outputs step by step.', 'bullet', 'openai', 0.91, 'approved'),\n  ('11111111-1111-1111-1111-111111111111', 3, 'Why It Matters', 'Foundation of most food chains\nProduces the oxygen we breathe\nRemoves CO2 from atmosphere', 'Connect to everyday life — breathing, eating.', 'bullet', 'openai', 0.88, 'unreviewed'),\n  ('11111111-1111-1111-1111-111111111111', 4, 'Key Vocabulary', 'Chlorophyll\nChloroplast\nGlucose\nPhotosynthesis', 'Have students define each term before moving on.', 'bullet', 'openai', 0.82, 'unreviewed'),\n  ('11111111-1111-1111-1111-111111111111', 5, 'Recap', 'Photosynthesis = sunlight to food\nInputs: light, water, CO2\nOutputs: glucose, oxygen', 'Quick recap — ask students to repeat the equation.', 'bullet', 'openai', 0.93, 'approved')\non conflict do nothing;\n\ninsert into presentations (title, topic, audience, tone, template_id)\nselect 'Q3 Investor Update', 'quarterly business performance', 'investors and board members', 'investor pitch', id\nfrom design_templates where name = 'Boardroom Blue'\non conflict do nothing;